// The catalogue of open typefaces (Fontsource families with their weights,
// axes, subsets and character), generated by scripts/typefaces/catalogue.ts
// and shipped as a static file of the editor; loaded on first use.

export interface Typeface {
  id: string;
  family: string;
  category: 'sans-serif' | 'serif' | 'display' | 'monospace' | 'handwriting' | 'other';
  weights: number[];
  italic: boolean;
  variable: boolean;
  /** variable families: the range of each axis */
  axes?: Record<string, [number, number]>;
  subsets: string[];
  license: string;
  tags: string[];
  /** where the family is good, when described by hand */
  for?: ('title' | 'text' | 'ui' | 'quote' | 'number' | 'code')[];
  /** families that go with it */
  pairs?: string[];
  /** something worth knowing (caps only…) */
  note?: string;
}

import { dataLoader } from '../data.ts';

export type Catalogue = { pin: string; fonts: Typeface[] };

export { TAGS } from '../../../../scripts/typefaces/tags.ts';

/** the catalogue, fetched once; a failed read is not kept, so the next call tries again */
export const loadCatalogue = dataLoader<Catalogue>('/typefaces/catalogue.json', 'the typeface catalogue');
